import { OverlayScope, Button, openDrawer } from "march/ui"

// telefon taslağı: çekmece ekranın içinde açılır, sayfayı örtmez
export function PhoneMock() {
  return <OverlayScope class="m-card" sx={{ p: 3, w: "sm" }}>
    <div sx={{ flex: "col", gap: 2 }}>
      <strong>HADİ</strong>
      <Button size="sm" on:click={() => openDrawer(() => <p sx={{ p: 3 }}>Telefonun içindeki menü</p>, { title: "Menü", side: "bottom" })}>Menüyü aç</Button>
    </div>
  </OverlayScope>
}

import { OverlayScope, Button, openDrawer, openDialog } from "march/ui"

// OverlayScope'un özellikleri: class (sabit ya da canlı), içerik; içinde açılan katman kutuda kalır, target: "page"
// sayfaya çıkarır
export function OverlayScopeLab() {
  let $dark = false
  return <OverlayScope class={() => ($dark ? "lab-scope lab-dark" : "lab-scope")}>
    <Button size="sm" on:click={() => $dark = !$dark}>Sınıfı değiştir</Button>
    <Button size="sm" on:click={() => openDrawer(() => <p>Kutudaki çekmece</p>, { title: "Çekmece" })}>Kutuda aç</Button>
    <Button size="sm" on:click={() => openDialog(() => <p>Bütün sayfa</p>, { title: "Sayfa", target: "page" })}>Sayfada aç</Button>
  </OverlayScope>
}

import { test, expect, renderTest } from "march/testing"
import { OverlayScopeLab } from "./OverlayScopeLab.tsx"

// OverlayScopeLab'in testleri: kaydedince Testler sekmesinde çalışır
test("kutu bir katman kapsamı", () => {
  const s = renderTest(() => <OverlayScopeLab />)
  expect(s.get(".lab-scope")?.classList.contains("m-overlay-scope")).toBe(true)
})

test("class canlı", async () => {
  const s = renderTest(() => <OverlayScopeLab />)
  await s.click("Sınıfı değiştir")
  expect(s.get(".lab-scope")?.classList.contains("lab-dark")).toBe(true)
})

test("içinde açılan çekmece kutunun içinde", async () => {
  const s = renderTest(() => <OverlayScopeLab />)
  await s.click("Kutuda aç")
  await s.flush(2)
  expect(s.get(".lab-scope")?.textContent).toContain("Kutudaki çekmece")
})
